ElapsedTime::ElapsedTime(
    std::shared_ptr<ElapsedTime> pTimeBase )
    : m_pTimeBase(std::move( pTimeBase )),
      m_fLastQueriedTime( 0.0 ),
      m_fStartTime( getCurrentTime() ),
      m_fFrozenTime( 0.0 ),
      m_bInPauseMode( false ),
      m_bInHoldMode( false )
